ee:variables.ee:set-variable:
%dw 2.0
output application/java
var errNamespace = error.errorType.namespace default ""
var errIdentifier = error.errorType.identifier default ""
var businessErrors = {
    INVALID_EVENT: { code: "INVALID_INVENTORY_EVENT", status: 400, message: "Required inventory field is missing or invalid." },
    UNKNOWN_MOVEMENT: { code: "UNSUPPORTED_MOVEMENT_TYPE", status: 400, message: "Movement type is not supported." },
    UNKNOWN_REFERENCE: { code: "REFERENCE_NOT_FOUND", status: 404, message: "SKU or location does not exist or is inactive." },
    VERSION_CONFLICT: { code: "VERSION_CONFLICT", status: 409, message: "Concurrent inventory update detected." },
    NEGATIVE_AVAILABLE: { code: "NEGATIVE_AVAILABLE_QUANTITY", status: 422, message: "Available quantity cannot be negative." }
}
var unavailableIds = ["CONNECTIVITY", "RETRY_EXHAUSTED", "TIMEOUT"]
var businessDefault = { code: "INVALID_INVENTORY_EVENT", status: 400, message: "Invalid inventory event." }
var unavailableInfo = { code: "SERVICE_UNAVAILABLE", status: 503, message: "A downstream system is temporarily unavailable. The event was sent for investigation.", level: "ERROR" }
var unexpectedInfo = { code: "INTERNAL_SERVER_ERROR", status: 500, message: "Unexpected inventory processing error.", level: "ERROR" }
---
if (errNamespace == "INVENTORY") ((businessErrors[errIdentifier] default businessDefault) ++ { level: "WARN" }) else (if (unavailableIds contains errIdentifier) unavailableInfo else unexpectedInfo)
